# -*- coding: utf-8 -*-
import json
s2 = "32店舗の売場変更と販促の準備は、いま〈件〉で管理されている。年に何本の企画を回したか、何回の売場変更をかけたか、という数え方である。同じものを〈作業時間〉で置き直すと、見え方が少し変わる。1件の企画は、本部での企画づくりと原稿確認から、店舗での棚替えと掲出、そして片づけまでを含む。件数では1と数えられるものが、時間では本部と店舗に分かれて積み上がる。件数がほぼ横ばいでも、時間の側が同じとは限らない。1件あたり何時間かかっているかは、いまの管理表からは出てこない。だから、いまの体制で足りているのかどうかも、件数の側からは判定できない。ここで申し上げたいのは、足りていないという断定ではない。単位を〈件〉から〈作業時間〉へ置き直すと、まだ誰も数えていない部分が出てくる、という点だけである。"

s3 = "その、まだ誰も数えていない部分に名前をつける。〈未確定売場時間〉と呼ぶ。販促の中身と売場の並びが決まらないまま、店舗が「たぶんこうなる」で先に動いている時間のことである。決まってから動けば一度で済む作業が、決まる前に動くと、下ごしらえと作り直しの二度になる。この二度目が未確定売場時間にあたる。新しい呼び名だけでは社内の書類に載らないので、いまお使いの言葉に置き直しておく。店舗運営部の様式では〈作業時間〉のうち手戻りと待ちにあたる部分。商品本部の様式では〈原価率〉に、直前の追加発注と値引き対応として乗ってくる部分。社長の様式では〈販管費〉に、パート人時として、また販促費として出てくる部分。呼び名は一つ、置き直す先は三つ、指しているものは同じである。"

s4 = "なぜ今か。2027-09-30 という日がある。契約上の終端日で、過ぎると取り返しがつかない。効くのは業態が食品スーパーの取引で、この日を握っているのは主要卸（一次問屋）である。卸の商談暦は御社の会計年度とは別に回っていて、秋の定番改訂の商談は毎年この日から逆算して組まれる。事業の側に訳すと、この日までに売場と販促が固まらなかったぶんは、翌期の粗利率と販管費へ持ち越される。ここに、まだ計算されていない量を一つ置く。秋の定番改訂商談までに確定していない売場の作業時間は、概算900〜1400時間（御社データからの算出、幅は店舗規模の差による）。毎年同じ周期で出る量である。この時間は営業利益の欄では直接読めない。財源の側で動くのは、店舗運営部が持つパート人時、同じく店舗運営部が持つ販促費、そして商品本部バイヤーが持つ廃棄である。間に合わなければ、この900〜1400時間は翌年へそのまま送られ、翌年の商談枠を圧迫する。"

s5 = "他の手段を検討しない、という話ではない。成り立つ条件のほうを書く。一つ目、パートを増やして内製する。人を増やすこと自体は成立する。ただし人手も枠も資金も一つの財布から出るので、そちらへ寄せた分だけ別の仕事が止まる。2027年秋に間に合わせるには2027-03-31までに採用と教育を終える必要があり、その期間は年末年始の販促準備とレジ応援の枠が止まる。この条件の下では、内製と年末販促の両立は成立しない。二つ目、主要卸（一次問屋）の販促支援を使う。これは御社の内側だけでは決まらない。卸の承認が要るという線が外側に引かれていて、承認が下りるまで着手日を動かせない。購買の様式に置き直すと、一つ目は原価率に人件費として乗るが取引条件は動かない。二つ目は取引条件は有利になり得るが、日程を相手に握られる。なお、いまの体制も、いまのお取引先も、御社が選ばれた結果として筋が通っている。書いたのは選択の当否ではなく、2027年秋という条件を置いたときに何が成り立たないか、である。"

s6 = "\n".join([
"ご提案は2026-11-02着手、12か月の売場・販促確定支援、年額180万〜900万円です。そもそもは媒体設計・制作・効果測定の販促支援で、卸の商談暦の側から売場確定を前倒しします。仕組みは開きます。媒体費・制作費の内訳と人月単価を出します。第三者の登録・認証は持っていません。並び比べで当社が残る根拠は、価格構成の開示と、食品スーパーの実名事例（○○ストア株式会社、関西）です。まず3か月・2店舗で試せます。",
"卸の承認は当社の実数で出します。承認取り付けの実績2件、実測日数20〜45日。他の手段を落とした条件は当社案にも当てます。当社も承認までは着手日を動かせません。逆算の最終着手期限2027-05-28（ここが決定の締切）の45日前、2027-04-13までに承認手続きへ入れなければ、当社案もこの条件では成立しません。成果責任の範囲は契約書に無いため、保証の言葉は使いません。",
"反論への回答は、いちばん慎重な方が訊く順に。値段は妥当か——内訳と人月単価を開示。効果が出なかったら——成果責任は契約に無く、3か月枠で先に確かめられます。店は回るか——現場向け資料を別に作ります（上向きとは論理が逆——人減らしではなく作業時間の平準化——なので流用できません）。来期の枠に響かないか——設備投資枠は使いません。",
"起案理由：秋の定番改訂の確定を前倒しし、確定待ちの作業時間を減らすため。上申サマリ（社長向け）：販管費で年240万〜480万円の下げ余地、営業利益はその範囲、設備投資枠は不使用。記入欄：対象カテゴリ【　】／対象店舗数【　】／実行に同意した座席【　】。費目を落とす両座席の実行同意も確認事項です。",
"〈座席ごとの量〉店舗運営部＝作業時間：年520〜780時間ぶん。商品本部バイヤー＝粗利率：対象カテゴリで年0.3〜0.6ポイント。",
"〈消す部分〉前の枚の900〜1400時間のうち520〜780時間。全部ではなく、残りは商談日程しだい。",
"〈誰がいつどの費目〉店舗運営部／2027-11-30／パート人時。店舗運営部／2028-01-31／販促費。商品本部バイヤー／2027-12-31／廃棄。",
])

slides=[("②",s2),("③",s3),("④",s4),("⑤",s5),("⑥",s6)]
banned=["消去","残余","カテゴリC","様相","必然化","問題化","内在的否定","措定","実然","前提化","共著者","蝶番","縮退","拘束の所在","エンテュメーメ","省略三段論法","外延","被覆率","M_0","M_i"]
for st,t in slides:
    n=len(t.replace("\n",""))
    ok = (700<=n<=900) if st=="⑥" else (200<=n<=450)
    print(st, n, "OK" if ok else "NG")
    for b in banned:
        if b in t: print("   BANNED:",b)
json.dump([{"stage":st,"text":t} for st,t in slides], open('/home/claude/work/tmp/slides_r1p1.json','w'), ensure_ascii=False, indent=1)
